template <typename T = int, size_t Size = 16>
class FixedArray {
    T data[Size];
public:
    using value_type = T;
    size_t size() const { return Size; }
};

// Instantiations using defaults:
FixedArray<> A;              // T=int, Size=16
FixedArray<double> B;        // T=double, Size=16

// Instantiation overriding defaults:
FixedArray<char, 8> C;       // T=char, Size=8
FixedArray<bool, 1> D;       // T=bool, Size=1 (requires default list ordering)
